function playTone(freq,duration,type='sine',volume=.035){
 if(muted)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audio.currentTime);gain.gain.setValueAtTime(volume,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch(_){ }
}
function update(dt){
 time+=dt;
 if(state==='playing'){
  distance+=speed*dt;player.vy+=1040*dt;player.y+=player.vy*dt;
  player.rot=Math.max(-.55,Math.min(.9,player.vy/550));
  speed=Math.min(325,250+score*2.2);
  while(distance>=spawnDistance){
   const last=enemies[enemies.length-1];
   let y=rand(110,groundY-80);
   if(last)y=Math.max(105,Math.min(groundY-85,last.y+rand(-130,130)));
   enemies.push({x:W+55,y,phase:rand(0,7),passed:false});
   spawnDistance+=rand(300,365);
  }
  for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];e.x-=speed*dt;
   if(!e.passed&&e.x<player.x){e.passed=true;score++;scoreNode.textContent=score;playTone(760,.1,'sine',.045);burst(player.x+15,player.y-15,'#ffd56b',5)}
   const ey=e.y+Math.sin(time*3+e.phase)*6;
   if(Math.hypot(player.x-e.x,player.y-5-ey)<39){endGame();break}
   if(e.x<-70)enemies.splice(i,1);
  }
  if(player.y<38){player.y=38;player.vy=30}
  if(player.y>groundY-42){player.y=groundY-42;endGame()}
 }
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
}
function render(dt){
 drawBackground(dt);
 // airborne crumbs trailing the skater
 if(state==='playing'&&Math.random()<.2)particles.push({x:player.x-33,y:player.y+13,vx:-rand(15,55),vy:rand(-20,25),life:.4,max:.4,r:rand(1,3),color:'#f8c56d'});
 for(const e of enemies)drawEnemy(e);
 drawPlayer();drawParticles(dt);
 if(state==='ready'){
  ctx.save();ctx.globalAlpha=.83;roundRect(360,376,240,40,20,'#fff5de');ctx.fillStyle='#885c3c';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font="700 15px 'DM Sans',sans-serif";ctx.fillText('TAP OR PRESS SPACE TO HOP',480,396);ctx.restore();
  // faint hint arrows
  ctx.strokeStyle='#e49a5e';ctx.globalAlpha=.7;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(487,424);ctx.lineTo(487,441);ctx.moveTo(481,435);ctx.lineTo(487,441);ctx.lineTo(493,435);ctx.stroke();ctx.globalAlpha=1;
 }
}
function startGame(){
 state='playing';score=0;distance=0;speed=250;spawnDistance=340;enemies=[];particles=[];player={x:220,y:255,vy:0,rot:0,blink:0};scoreNode.textContent='0';scoreNode.classList.add('show');overlay.classList.add('hidden');flap();
}
function endGame(){
 if(state!=='playing')return;state='over';scoreNode.classList.remove('show');burst(player.x,player.y,'#f16e42',20);playTone(165,.28,'triangle',.07);
 if(score>best){best=score;localStorage.setItem('crunchCruisersBest',best);bestNode.innerHTML=`BEST&nbsp; ${best}`;badgeNode.textContent='🏆  new personal best!'}else badgeNode.textContent='🌶️  the heat got you!';
 titleNode.innerHTML=`CRUNCH<br><em>DOWN!</em>`;descriptionNode.innerHTML=`You dodged <strong>${score}</strong> spicy chip${score===1?'':'s'}. Ready for another run?`;startButton.innerHTML='PLAY AGAIN&nbsp; ↻';overlay.classList.remove('hidden');
}
function flap(){
 if(state==='ready'){startGame();return}
 if(state!=='playing')return;
 player.vy=-370;player.rot=-.4;playTone(440,.09,'triangle',.025);burst(player.x-17,player.y+15,'#fff0c1',3);
}
function onKey(e){if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){e.preventDefault();if(!overlay.classList.contains('hidden')){if(state==='ready'||state==='over')startGame()}else flap()}}
window.addEventListener('keydown',onKey);
canvas.addEventListener('pointerdown',e=>{e.preventDefault();if(state==='ready'||state==='over')startGame();else flap()});
startButton.addEventListener('click',()=>{if(state==='ready'||state==='over')startGame()});
soundButton.addEventListener('click',()=>{muted=!muted;soundButton.textContent=muted?'♫̸':'♫';soundButton.setAttribute('aria-label',muted?'Turn sound on':'Turn sound off');if(!muted)playTone(660,.08)});
let prev=0;
function loop(stamp){const dt=Math.min(.04,(stamp-prev)/1000||0);prev=stamp;update(dt);render(dt);requestAnimationFrame(loop)}
requestAnimationFrame(loop);
})();
</script>
</body>
